#include <iostream>

constexpr bool isLeapYear(int year) noexcept {
    return (year % 400 == 0) || (year % 4 == 0 && year % 100 != 0);
}

constexpr int getNumberOfDaysInMonth(int year, int month) noexcept {
    if (month == 1 || month == 3 || month == 5 || month == 7 ||
        month == 8 || month == 10 || month == 12) {
        return 31;
    }
    if (month == 4 || month == 6 || month == 9 || month == 11) {
        return 30;
    }
    if (month == 2) {
        return isLeapYear(year) ? 29 : 28;
    }
    return 0;
}

int main() {
    int year = 2024;
    int month = 2;
    std::cout << "Year " << year << " is leap: " << (isLeapYear(year) ? "true" : "false") << "\n";
    std::cout << "Month " << month << " days: " << getNumberOfDaysInMonth(year, month) << "\n";
    return 0;
}

body.vi:
Triển khai từ trên xuống (top-down implementation) bắt đầu từ hàm ở đỉnh biểu đồ phân cấp (thường là `main`) và đi dần xuống các lá bên dưới. Để có thể biên dịch và kiểm tra luồng điều khiển của chương trình ngay cả khi các hàm con chưa được viết hoàn chỉnh, ta sử dụng **hàm giả lập (stub)**.

Stub là một phiên bản rút gọn, đơn giản và tạm thời của hàm. Một stub thường chỉ in ra thông báo rằng nó đã được gọi kèm theo giá trị tham số nhận vào, hoặc trả về một giá trị cố định giả định. Ví dụ, trong quá trình phát triển `main`, ta có thể tạo stub:
```cpp
void printMonth(int year, int month) {
    std::cout << "printMonth called with: " << month << " " << year << "\n";
}
```
Cách làm này giúp xác thực sớm cấu trúc chương trình, cơ chế truyền tham số và giao diện người dùng mà không bị sa lầy vào thuật toán phức tạp.

body.en:
Top-down implementation starts with the top-level function in the structure chart (typically `main`) and progresses downward toward the leaves. To compile, run, and verify program flow before low-level subfunctions are fully written, developers employ **stubs**.

A stub is a lightweight, simplified, temporary implementation of a function. It commonly displays an informational test message showing it was invoked along with parameter values, or returns a hardcoded placeholder value. For example, while building `main`, a stub for `printMonth` may look like:
```cpp
void printMonth(int year, int month) {
    std::cout << "printMonth called with: " << month << " " << year << "\n";
}
```
This enables early verification of control flow, argument passing, and interface interactions without prematurely diving into intricate algorithmic details.

example.code:
#include <iostream>

// Bottom-up component: thoroughly tested leaf function
bool isLeapYear(int year) {
    return (year % 400 == 0) || (year % 4 == 0 && year % 100 != 0);
}

// Stub: temporary implementation for a higher-level subproblem
void printMonthTitleStub(int year, int month) {
    std::cout << "[Stub] Rendering title for month " << month << ", year " << year << "\n";
}

// Stub: body printing placeholder
void printMonthBodyStub(int year, int month) {
    std::cout << "[Stub] Rendering body for month " << month << ", year " << year << "\n";
}

void printMonth(int year, int month) {
    printMonthTitleStub(year, month);
    printMonthBodyStub(year, month);
}

int main() {
    // Driver test for leaf function
    std::cout << "Test isLeapYear(2000): " << (isLeapYear(2000) ? "PASS" : "FAIL") << "\n";

    // Top-down control flow test using stubs
    int sampleYear = 2023;
    int sampleMonth = 8;
    printMonth(sampleYear, sampleMonth);

    return 0;
}

#include <iostream>
#include <iomanip>
#include <string_view>

constexpr bool isLeapYear(int year) noexcept {
    return (year % 400 == 0) || (year % 4 == 0 && year % 100 != 0);
}

constexpr int getNumberOfDaysInMonth(int year, int month) noexcept {
    if (month == 1 || month == 3 || month == 5 || month == 7 ||
        month == 8 || month == 10 || month == 12) {
        return 31;
    }
    if (month == 4 || month == 6 || month == 9 || month == 11) {
        return 30;
    }
    if (month == 2) {
        return isLeapYear(year) ? 29 : 28;
    }
    return 0;
}

constexpr int getTotalNumberOfDays(int year, int month) noexcept {
    int total = 0;
    for (int y = 1800; y < year; ++y) {
        total += isLeapYear(y) ? 366 : 365;
    }
    for (int m = 1; m < month; ++m) {
        total += getNumberOfDaysInMonth(year, m);
    }
    return total;
}

constexpr int getStartDay(int year, int month) noexcept {
    constexpr int startDay1800 = 3; // 1/1/1800 was Wednesday
    return (getTotalNumberOfDays(year, month) + startDay1800) % 7;
}

std::string_view getMonthName(int month) noexcept {
    constexpr std::string_view names[] = {
        "", "January", "February", "March", "April", "May", "June",
        "July", "August", "September", "October", "November", "December"
    };
    if (month >= 1 && month <= 12) return names[month];
    return "";
}

void printMonthTitle(int year, int month) {
    std::cout << "        " << getMonthName(month) << " " << year << "\n";
    std::cout << "-----------------------------\n";
    std::cout << " Sun Mon Tue Wed Thu Fri Sat\n";
}

void printMonthBody(int year, int month) {
    int startDay = getStartDay(year, month);
    int daysInMonth = getNumberOfDaysInMonth(year, month);

    for (int i = 0; i < startDay; ++i) {
        std::cout << "    ";
    }
    for (int day = 1; day <= daysInMonth; ++day) {
        std::cout << std::setw(4) << day;
        if ((day + startDay) % 7 == 0) {
            std::cout << "\n";
        }
    }
    if ((daysInMonth + startDay) % 7 != 0) {
        std::cout << "\n";
    }
}

void printMonth(int year, int month) {
    printMonthTitle(year, month);
    printMonthBody(year, month);
}

int main() {
    // Demonstrate printing August 2013
    printMonth(2013, 8);
    return 0;
}
